**COLUMN-LEVEL ENCRYPTION**

```sql
-- Install pgcrypto extension
CREATE EXTENSION pgcrypto;

-- Create table with encrypted columns
CREATE TABLE customers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email text NOT NULL,
  ssn_encrypted bytea,
  credit_card_encrypted bytea,
  created_at timestamptz DEFAULT now()
);

-- Encryption key (store securely!)
-- In production, use KMS or vault
CREATE TABLE encryption_keys (
  id text PRIMARY KEY,
  key bytea NOT NULL
);

-- Encrypt function
CREATE OR REPLACE FUNCTION encrypt_sensitive(data text, key_id text)
RETURNS bytea AS $$
DECLARE
  key_data bytea;
BEGIN
  SELECT key INTO key_data FROM encryption_keys WHERE id = key_id;
  RETURN pgp_sym_encrypt(data, key_data);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Decrypt function  
CREATE OR REPLACE FUNCTION decrypt_sensitive(encrypted_data bytea, key_id text)
RETURNS text AS $$
DECLARE
  key_data bytea;
BEGIN
  SELECT key INTO key_data FROM encryption_keys WHERE id = key_id;
  RETURN pgp_sym_decrypt(encrypted_data, key_data);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Usage
INSERT INTO customers (email, ssn_encrypted, credit_card_encrypted)
VALUES (
  'customer@example.com',
  encrypt_sensitive('123-45-6789', 'ssn_key'),
  encrypt_sensitive('4111111111111111', 'cc_key')
);
```

**ACCESS CONTROL**

```sql
-- Only HR can see SSN
GRANT SELECT ON customers TO hr_role;
GRANT EXECUTE ON FUNCTION decrypt_sensitive(bytea, text) TO hr_role;

-- Finance can see credit card
GRANT SELECT ON customers TO finance_role;
GRANT EXECUTE ON FUNCTION decrypt_sensitive(bytea, text) TO finance_role;

-- Application cannot see raw data
-- Application uses blind indexes for searching
CREATE INDEX ON customers USING bloom(ssn_encrypted);
```
